import IndexWorker from './index.worker.js?worker';
import { BIM_INDEX_VERSION } from './index-version.js';

const CACHE_SUFFIX = `:bim-index-v${BIM_INDEX_VERSION}`;

/**
 * Obtains BIM indexes: hosted models download the JSON generated by
 * `pnpm run convert:fragments`; IFCs opened by the user are indexed in a
 * worker and cached next to their Fragment in IndexedDB.
 */
export class BimIndexService {
  constructor({ cache, wasmPath }) {
    this.cache = cache;
    this.wasmPath = wasmPath;
    this.worker = null;
    this.pending = new Map();
    this.nextId = 1;
  }

  async loadHosted(entry) {
    if (!entry.bimIndex) return null;
    const url = entry.bimIndexHash ? `${entry.bimIndex}?v=${entry.bimIndexHash}` : entry.bimIndex;
    const response = await fetch(url);
    if (!response.ok) throw new Error(`índice BIM não encontrado (${response.status})`);
    return response.json();
  }

  async getCached(hash) {
    if (!hash || !this.cache) return null;
    try {
      const entry = await this.cache.get(`${hash}${CACHE_SUFFIX}`);
      return entry?.index || null;
    } catch {
      return null;
    }
  }

  async putCached(hash, index) {
    if (!hash || !this.cache) return;
    try {
      await this.cache.put({ hash: `${hash}${CACHE_SUFFIX}`, index, createdAt: Date.now() });
    } catch (error) {
      console.warn('Não foi possível guardar o índice BIM no cache local:', error);
    }
  }

  /** Indexes an IFC buffer in a worker. The buffer is copied, never transferred. */
  buildFromIfc(buffer, onProgress) {
    if (!this.worker) {
      this.worker = new IndexWorker();
      this.worker.onmessage = (event) => {
        const { id, type } = event.data || {};
        const job = this.pending.get(id);
        if (!job) return;
        if (type === 'progress') job.onProgress?.(event.data.fraction, event.data.label);
        else if (type === 'done') { this.pending.delete(id); job.resolve(event.data.index); }
        else if (type === 'error') { this.pending.delete(id); job.reject(new Error(event.data.message)); }
      };
      this.worker.onerror = (event) => {
        const error = new Error(event.message || 'falha no processamento do índice BIM');
        this.pending.forEach((job) => job.reject(error));
        this.pending.clear();
        this.worker?.terminate();
        this.worker = null;
      };
    }
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject, onProgress });
      this.worker.postMessage({ id, buffer: buffer.slice(0), wasmPath: this.wasmPath });
    });
  }
}
